package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class EqualPartCutsTest {
 @Test public void areaEqualityUsesVisibleRectangleNotStoredAnswer(){Checker c=new Checker();for(int w=4;w<=9;w++)for(int h=3;h<=5;h++)for(int axis=0;axis<2;axis++){Question q=EqualPartCuts.make(w,h,axis);assertArrayEquals(new int[]{w,h,axis},EqualPartCuts.read(q));q.answers=new String[]{"25"};q.expression="poison";for(int cut=1;cut<100;cut++){int leftArea=w*h*cut,rightArea=w*h*(100-cut);assertEquals(leftArea==rightArea,c.check(q,List.of(),List.of(""+cut)).correct());}assertFalse(c.check(q,List.of(),List.of("")).correct());assertFalse(c.check(q,List.of(),List.of("100")).correct());q.prompt="bad";assertFalse(c.check(q,List.of(),List.of("50")).correct());}}
 @Test public void onlyReviewedGradeAndNormalFreshSupply(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(EqualPartCuts.ID,1));assertFalse(GlobalCurriculum.pack(p).inGrade(EqualPartCuts.ID,2));Generator g=new Generator(new Random(211));List<String> recent=new ArrayList<>();for(int i=0;i<36;i++){Question q=g.next(EqualPartCuts.ID,recent,false,CurriculumLimits.NONE);assertNotNull(EqualPartCuts.read(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());}GlobalCurriculum.chooseCountry(p,"AQ");assertFalse(GlobalCurriculum.available(p).stream().anyMatch(s->EqualPartCuts.supports(s.id)));}
}
